 :root{--ink:#252722;--muted:#8a887d;--paper:#f4f1e9;--cream:#e8e3d6;--line:#ded9cc;--dark:#171a1a;--dark-soft:#222625;--gold:#d8aa66;--gold-light:#f1d4a0;--sage:#8a9b79;--red:#c96c5a;--serif:'Spectral',Georgia,serif;--sans:'DM Sans',system-ui,sans-serif}*{box-sizing:border-box}html{background:var(--paper)}body{margin:0;color:var(--ink);font-family:var(--sans);min-height:100vh;background:radial-gradient(ellipse at 75% -20%,#fffdf7 0,transparent 54%),var(--paper)}button{font:inherit}.app-shell{width:min(1360px,100%);margin:0 auto;padding:0 50px 22px}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:11px;align-items:center;text-decoration:none;color:var(--ink);font-size:13px;font-weight:700;letter-spacing:2px}.brand b{font-weight:500;color:#8f7655}.brand-mark{display:grid;place-items:center;width:27px;height:27px;color:var(--gold);border:1px solid #d5c6aa;border-radius:50%;font-size:15px}.chapter{color:#858276;font-size:9px;font-weight:700;letter-spacing:1.55px;display:flex;gap:11px;align-items:center}.chapter-dot,.live-dot{height:6px;width:6px;border-radius:50%;background:#a6814c;display:inline-block;box-shadow:0 0 0 3px #a6814c22}.chapter-divider{color:#c3b9a7}.sound-button{border:1px solid var(--line);border-radius:18px;padding:8px 12px;background:#fff9;color:#7e786b;font-size:12px;cursor:pointer}.sound-button span{font-size:10px;margin-left:4px}.intro-row{padding:27px 0 21px;display:flex;justify-content:space-between;align-items:flex-end}.eyebrow,.section-kicker{font-size:9px;letter-spacing:1.6px;font-weight:700;color:#9a8665;margin:0 0 5px}.intro-row h1{font:600 31px/1.1 var(--serif);margin:0;letter-spacing:-.3px}.intro-row h1 i{font-weight:500;color:#9d7546}.run-stats{display:flex;gap:18px;color:#908a7c;font-size:10px;letter-spacing:.5px;padding:6px 0}.run-stats span{white-space:nowrap}.run-stats b{color:#4d4a41;font-size:10px;margin-left:4px}.class-screen{min-height:590px;border:1px solid #ded9cc;background:linear-gradient(125deg,#ede8dc,#f7f4ec 47%,#eee9dd);display:flex;align-items:center;flex-direction:column;justify-content:center;padding:35px 24px;position:relative;overflow:hidden}.class-screen:before,.class-screen:after{content:'✦';position:absolute;color:#d4c8b3;font-size:20px;opacity:.7}.class-screen:before{top:29px;left:34px}.class-screen:after{bottom:28px;right:34px}.class-copy{text-align:center;margin-bottom:25px}.ornament{color:#a68a62;font-weight:700;letter-spacing:2px;font-size:9px}.class-copy p{font:500 17px/1.55 var(--serif);color:#605b50;margin:13px 0 0}.class-grid{display:grid;grid-template-columns:repeat(3,minmax(170px,220px));gap:15px}.class-card{appearance:none;cursor:pointer;text-align:left;position:relative;min-height:230px;padding:20px 18px 17px;border:1px solid #d8d1c3;background:#f8f5ed;color:var(--ink);transition:transform .18s,border .18s,box-shadow .18s}.class-card:hover{transform:translateY(-3px);border-color:#b89869;box-shadow:0 9px 22px #54432b12}.class-card.selected{border:1px solid #ae8751;box-shadow:inset 0 0 0 1px #ae8751,0 8px 18px #54432b15;background:#fffcf5}.class-card.selected:after{content:'✓';position:absolute;right:13px;top:13px;display:grid;place-items:center;width:20px;height:20px;background:#aa8451;color:white;border-radius:50%;font-size:11px}.class-art{width:63px;height:63px;border-radius:50%;display:grid;place-items:center;margin:0 auto 15px;font-size:31px;background:radial-gradient(circle,#f4e3c2,#e3d5ba 68%,#d1c0a3);box-shadow:inset 0 0 0 1px #c7b38f,0 4px 11px #76613c17}.class-card:nth-child(2) .class-art{background:radial-gradient(circle,#d8d7e8,#c5c6da 68%,#a7a9c1)}.class-card:nth-child(3) .class-art{background:radial-gradient(circle,#d9e3ce,#bfceb1 68%,#98aa86)}.class-name{text-align:center;font:700 19px var(--serif)}.class-subtitle{text-align:center;color:#a1845e;font-weight:700;font-size:8px;letter-spacing:1.45px;margin:3px 0 12px}.class-desc{text-align:center;color:#777165;font-size:10px;line-height:1.5;min-height:30px}.class-stats{display:flex;justify-content:center;gap:13px;border-top:1px solid #e6e0d4;margin-top:12px;padding-top:10px;color:#8e887a;font-size:9px}.class-stats b{color:#4c4a41}.primary-button{background:#282a26;color:#f5ead7;border:1px solid #282a26;padding:13px 23px;font-size:10px;font-weight:700;letter-spacing:1.05px;text-transform:uppercase;cursor:pointer;transition:background .15s,transform .15s}.primary-button span{font-size:16px;margin-left:19px;color:var(--gold-light)}.primary-button:hover:not(:disabled){background:#44453c;transform:translateY(-1px)}.primary-button:disabled{opacity:.42;cursor:not-allowed}.begin-button{margin-top:22px;min-width:236px}.class-footnote{font-size:9px;color:#a39b8d;margin:13px 0 0;letter-spacing:.5px}.game-screen[hidden],.class-screen[hidden]{display:none}.battle-layout{display:grid;grid-template-columns:minmax(0,1.56fr) minmax(330px,.86fr);gap:19px;align-items:stretch}.battle-card,.intent-card,.action-card,.log-card{border:1px solid var(--line);background:#faf8f2}.battle-card{min-width:0;overflow:hidden}.battle-topline{height:42px;padding:0 17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:9px;letter-spacing:1.2px;font-weight:700;color:#8f7a5a}.encounter-label{display:flex;align-items:center;gap:9px}.difficulty{font-size:9px;color:#9e998c;letter-spacing:.5px;font-weight:500}.scene{height:336px;position:relative;overflow:hidden;background:linear-gradient(180deg,#313e43 0%,#60706b 43%,#8c8268 75%,#726a58 100%);isolation:isolate}.scene:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,#18242a55,#21272108 52%,#282a22a8);z-index:1}.scene-moon{position:absolute;width:66px;height:66px;background:#e6d9b8;border-radius:50%;top:34px;right:19%;box-shadow:0 0 55px 17px #e6d9b833}.scene-mountains{position:absolute;inset:80px -6% 52px;background:#43564e;clip-path:polygon(0 45%,11% 22%,18% 44%,28% 0,40% 43%,52% 12%,63% 50%,75% 17%,89% 46%,100% 24%,100% 100%,0 100%);opacity:.7}.scene-mountains:after{content:'';position:absolute;inset:25px 0 0;background:#34443e;clip-path:polygon(0 56%,16% 12%,30% 54%,47% 20%,63% 65%,80% 6%,100% 53%,100% 100%,0 100%)}.scene-ruin{position:absolute;bottom:60px;width:90px;height:173px;background:#303933;opacity:.64;clip-path:polygon(12% 0,67% 0,67% 11%,84% 11%,84% 17%,100% 17%,100% 22%,86% 22%,86% 100%,0 100%,0 33%,12% 33%)}.ruin-one{left:7%}.ruin-two{right:9%;height:124px;transform:scaleX(-1);opacity:.45}.scene-mist{position:absolute;z-index:2;left:-10%;width:120%;height:35px;border-radius:50%;background:#d7d2bd25;filter:blur(11px)}.mist-one{bottom:82px}.mist-two{bottom:56px;left:12%;opacity:.55}.combatant{position:absolute;z-index:3;bottom:42px;width:35%;height:250px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;transition:transform .25s,filter .2s}.hero-combatant{left:8%}.enemy-combatant{right:8%}.hero-figure,.enemy-figure{z-index:2;position:relative;font-size:112px;line-height:1;filter:drop-shadow(0 11px 8px #1119);transform-origin:bottom center;user-select:none}.hero-figure{font-size:103px}.enemy-figure{font-size:112px;animation:idle 2.8s ease-in-out infinite}.hero-glow,.enemy-aura{position:absolute;bottom:18px;width:160px;height:130px;border-radius:50%;filter:blur(24px);background:#dec0892a}.enemy-aura{background:#cb795640}.ground-shadow{height:14px;width:98px;border-radius:50%;background:#1119;margin-top:-3px;filter:blur(4px)}.scene-name{color:#f2e8ce;position:relative;z-index:3;font-size:8px;letter-spacing:1.7px;font-weight:700;margin-top:10px;text-shadow:0 2px 6px #000}.scene-caption{z-index:4;position:absolute;bottom:0;left:0;right:0;height:31px;padding:0 15px;display:flex;justify-content:space-between;align-items:center;color:#eee1c6;font-size:8px;letter-spacing:1.4px;font-weight:700;background:linear-gradient(90deg,#181d1ccc,#181d1c55)}.scene-vignette{z-index:2;position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 70px #171a1a70}.hit-flash{position:absolute;z-index:6;inset:0;background:#f5d490;opacity:0;pointer-events:none}.hit-flash.flash{animation:flash .4s ease-out}.enemy-combatant.hit{animation:shake .36s}.hero-combatant.hit{animation:shake .36s}.scene-toast{position:absolute;z-index:8;top:30%;left:50%;transform:translate(-50%,-50%);font:700 27px var(--serif);color:#fff1d2;text-shadow:0 2px 9px #111;opacity:0;pointer-events:none}.scene-toast.show{animation:floattext .95s ease-out}.combatant-bars{display:grid;grid-template-columns:1fr 30px 1fr;padding:18px 20px 19px;align-items:center;gap:11px}.unit-heading{display:flex;justify-content:space-between;align-items:center;gap:5px;margin-bottom:8px;white-space:nowrap}.unit-heading b{font:700 12px var(--serif)}.unit-heading small{font-size:7px;letter-spacing:1px;color:#9d8b6d;margin-left:5px}.unit-icon{color:#b18a55;font-size:11px;margin-right:3px}.enemy-unit-icon{color:#b77667}.hp-numbers{font-size:9px;color:#777366}.health-track{height:5px;background:#e4e0d6;border-radius:5px;overflow:hidden}.health-fill{height:100%;border-radius:5px;transition:width .35s ease}.hero-health{background:#889978}.enemy-health{background:#bd7768}.versus-mark{font:italic 10px var(--serif);color:#b4ad9e;text-align:center}.side-column{display:flex;flex-direction:column;gap:12px;min-width:0}.intent-card{padding:14px 16px 13px;background:#f1ede2}.section-kicker{font-size:8px;letter-spacing:1.4px;color:#978363;margin:0}.intent-icon{float:right;color:#bf9d6c;font-size:14px}.intent-main{display:flex;align-items:center;gap:11px;margin-top:10px}.intent-symbol{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;color:#b57768;background:#e7d9ca;font-size:15px}.intent-main b{font:600 13px var(--serif)}.intent-main p{margin:3px 0 0;color:#918c7e;font-size:9px}.action-card{padding:15px 16px 12px;flex:1}.action-header{display:flex;justify-content:space-between;align-items:center}.action-header h2{font:600 19px var(--serif);margin:2px 0 0}.turn-token{color:#b5905d;border:1px solid #dbcfba;width:26px;height:26px;display:grid;place-items:center;border-radius:50%;font-size:11px}.action-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px}.action-button{position:relative;min-height:53px;padding:8px 10px;text-align:left;display:flex;align-items:center;gap:9px;border:1px solid #e2ddd1;background:#f8f6f0;color:#36362f;cursor:pointer;transition:border-color .15s,background .15s,transform .15s}.action-button:hover:not(:disabled){border-color:#bd9d6e;background:#fffaf0;transform:translateY(-1px)}.action-button:disabled{opacity:.45;cursor:not-allowed}.action-icon{font-size:17px;width:21px;text-align:center;color:#ac8453}.action-button:nth-child(2) .action-icon{color:#9384ae}.action-button:nth-child(3) .action-icon{color:#80966f}.action-button:nth-child(4) .action-icon{color:#b87668}.action-name{display:block;font:700 11px var(--serif)}.action-detail{display:block;color:#9a9588;font-size:8px;margin-top:2px}.action-cost{position:absolute;top:5px;right:6px;font-size:7px;color:#9a886a}.action-hint{margin-top:9px;font-size:8px;color:#a09a8d;text-align:center;min-height:11px}.log-card{padding:12px 15px 9px;min-height:101px}.log-live{float:right;color:#a2a08e;font-size:7px;letter-spacing:.9px}.log-live:before{content:'';display:inline-block;width:5px;height:5px;background:#8b9b78;border-radius:50%;margin:0 5px 1px 0}.battle-log{display:flex;flex-direction:column;gap:5px;margin-top:8px}.log-entry{font-size:9px;color:#777467;line-height:1.35}.log-entry:first-child{color:#46483f}.log-entry .log-highlight{color:#a57746;font-weight:700}.game-footer{height:42px;display:flex;justify-content:space-between;align-items:end;color:#a7a092;font-size:8px;letter-spacing:1.3px}.game-footer button{font:600 9px var(--sans);letter-spacing:.35px;color:#8d8779;background:none;border:0;cursor:pointer;padding:7px}.game-footer button:hover{color:#5d594f}.modal-backdrop{position:fixed;inset:0;z-index:20;background:#171a1ad9;display:grid;place-items:center;padding:20px}.modal-backdrop[hidden]{display:none}.result-modal{width:min(420px,100%);padding:37px 38px 32px;text-align:center;background:#f4f0e7;border:1px solid #c9b894;box-shadow:0 20px 70px #0006;position:relative}.result-seal{width:48px;height:48px;border:1px solid #c8ae7e;color:#a88048;border-radius:50%;display:grid;place-items:center;margin:0 auto 15px;font-size:19px}.result-modal h2{font:600 31px var(--serif);margin:0;color:#292a25}.result-modal>p:not(.eyebrow){font:13px/1.6 var(--serif);color:#777164;margin:9px auto 16px;max-width:290px}.result-modal .eyebrow{margin-bottom:5px}.reward-line{color:#9a7648;font-size:10px;letter-spacing:.4px;margin:0 0 21px}.result-modal .primary-button{min-width:210px}.toast{position:fixed;left:50%;bottom:22px;z-index:30;transform:translate(-50%,20px);background:#292c28;color:#f4ead8;padding:11px 18px;font-size:11px;box-shadow:0 5px 20px #0002;opacity:0;pointer-events:none;transition:all .22s}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes idle{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}@keyframes flash{0%{opacity:.65}100%{opacity:0}}@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-11px) rotate(-4deg)}75%{transform:translateX(9px) rotate(3deg)}}@keyframes floattext{0%{opacity:0;top:42%}20%{opacity:1}100%{opacity:0;top:20%}}
@media(max-width:850px){.app-shell{padding:0 24px 18px}.battle-layout{grid-template-columns:minmax(0,1.25fr) minmax(300px,.85fr);gap:12px}.scene{height:310px}.combatant{width:40%}.hero-figure{font-size:85px}.enemy-figure{font-size:95px}.action-card{padding:13px}.action-button{padding:7px;gap:6px}.unit-heading b{font-size:11px}.unit-heading small{display:none}.combatant-bars{padding:14px 12px;gap:6px}}
@media(max-width:650px){body{min-height:100dvh}.app-shell{padding:0 14px calc(13px + env(safe-area-inset-bottom))}.topbar{height:58px}.brand{font-size:11px;letter-spacing:1.4px;gap:7px}.brand-mark{width:24px;height:24px}.chapter{font-size:7px;letter-spacing:.85px;gap:6px}.sound-button{padding:6px 8px;font-size:11px}.sound-button span{display:none}.intro-row{padding:19px 0 14px;align-items:center}.intro-row h1{font-size:25px}.eyebrow{font-size:8px}.run-stats{gap:9px;font-size:8px}.run-stats b{font-size:8px}.class-screen{min-height:calc(100dvh - 126px);padding:24px 14px}.class-copy{margin-bottom:17px}.class-copy p{font-size:15px}.class-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;width:100%}.class-card{min-height:206px;padding:12px 7px}.class-art{width:52px;height:52px;font-size:26px;margin-bottom:11px}.class-name{font-size:16px}.class-subtitle{font-size:7px;letter-spacing:.8px}.class-desc{font-size:9px;min-height:42px}.class-stats{gap:6px;font-size:8px;flex-wrap:wrap;margin-top:8px;padding-top:8px}.begin-button{margin-top:19px}.class-footnote{font-size:8px;text-align:center}.battle-layout{display:flex;flex-direction:column;gap:9px}.battle-topline{height:36px;padding:0 12px}.scene{height:clamp(210px,38vh,330px)}.scene-moon{width:48px;height:48px;top:25px}.combatant{height:78%;bottom:30px;width:42%}.hero-combatant{left:1%}.enemy-combatant{right:1%}.hero-figure{font-size:clamp(70px,23vw,100px)}.enemy-figure{font-size:clamp(78px,25vw,109px)}.ground-shadow{width:73px;height:10px}.scene-name{font-size:7px;margin-top:7px}.hero-glow,.enemy-aura{width:115px;height:95px}.scene-caption{height:26px;font-size:7px;padding:0 10px}.combatant-bars{padding:12px 10px;grid-template-columns:1fr 22px 1fr;gap:5px}.unit-heading{margin-bottom:6px}.unit-heading b{font-size:10px}.hp-numbers{font-size:8px}.health-track{height:4px}.side-column{display:grid;grid-template-columns:1fr 1.65fr;gap:8px}.intent-card{grid-column:1;padding:11px 10px}.intent-main{gap:7px;margin-top:8px}.intent-symbol{width:27px;height:27px;font-size:12px;flex:0 0 auto}.intent-main b{font:600 11px var(--serif)}.intent-main p{font-size:8px;line-height:1.35}.section-kicker{font-size:7px;letter-spacing:1px}.action-card{grid-column:2;grid-row:span 2;padding:11px 10px 7px}.action-header h2{font-size:16px}.turn-token{width:22px;height:22px;font-size:9px}.action-grid{gap:6px;margin-top:9px}.action-button{min-height:48px;padding:6px 7px}.action-icon{font-size:14px;width:17px}.action-name{font-size:10px}.action-detail{font-size:7px}.action-cost{top:3px;right:4px;font-size:6px}.action-hint{font-size:7px;margin-top:6px}.log-card{grid-column:1;padding:10px;min-height:0}.battle-log{gap:4px;margin-top:7px}.log-entry{font-size:8px}.game-footer{height:32px;font-size:7px}.game-footer button{font-size:8px}.result-modal{padding:30px 25px 26px}.result-modal h2{font-size:28px}}
@media(max-width:370px){.app-shell{padding-left:9px;padding-right:9px}.class-card{padding-left:4px;padding-right:4px}.class-desc{font-size:8px}.class-stats{font-size:7px}.run-stats{gap:5px}.run-stats b{font-size:7px}.intent-card{padding:9px 7px}.intent-main b{font-size:10px}}

const classes = {
  knight: { name:'Knight', title:'THE IRONBOUND', icon:'🛡️', hp:38, focus:3, attack:8, armor:2, skill:'Shield Bash', skillIcon:'⛨', skillText:'11 dmg · stun', description:'A steadfast guardian who turns steel into a promise.', stats:'♥ 38 HP　 ⚔ 8 ATK　 ◈ 2 ARM' },
  mage: { name:'Mage', title:'THE SPELLWEAVER', icon:'🧙', hp:27, focus:4, attack:7, armor:0, skill:'Arcane Bolt', skillIcon:'✧', skillText:'14 magic dmg', description:'A keeper of old magic with a dangerous spark.', stats:'♥ 27 HP　 ✧ 4 FOC　 ☄ 7 ATK' },
  ranger: { name:'Ranger', title:'THE WILDSOUL', icon:'🏹', hp:31, focus:3, attack:8, armor:1, skill:'Aimed Shot', skillIcon:'➶', skillText:'13 dmg · true aim', description:'A patient hunter who never wastes an arrow.', stats:'♥ 31 HP　 ⚔ 8 ATK　 ◈ 1 ARM' }
};
const encounters = [
  { name:'Goblin Scout', icon:'👹', hp:21, attack:6, xp:24, caption:'THE OLD ROAD · DUSK', line:'A goblin leaps from the brush.' },
  { name:'Feral Direwolf', icon:'🐺', hp:29, attack:7, xp:32, caption:'THE BLACKPINE WOOD', line:'Yellow eyes gleam between the pines.' },
  { name:'Hollow Knight', icon:'💀', hp:37, attack:8, xp:42, caption:'THE FORGOTTEN WATCHTOWER', line:'An oathbreaker rises from the dust.' },
  { name:'Ogre Brute', icon:'👹', hp:47, attack:9, xp:52, caption:'THE ASHEN PASS', line:'The mountain shakes beneath its feet.' },
  { name:'The Cinder Wyrm', icon:'🐉', hp:72, attack:11, xp:100, caption:'THE CRUCIBLE · END OF ALL ROADS', line:'The Cinder Wyrm opens one burning eye.', boss:true }
];
let state = { classKey:null, hero:null, wave:0, xp:0, potions:2, guard:false, stunned:false, intent:null, over:false, sound:false, busy:false, log:[] };
const $ = id => document.getElementById(id);
const grid = $('class-grid');
Object.entries(classes).forEach(([key,c]) => {
  const card=document.createElement('button'); card.className='class-card'; card.type='button'; card.dataset.class=key;
  card.innerHTML=`<div class="class-art">${c.icon}</div><div class="class-name">${c.name}</div><div class="class-subtitle">${c.title}</div><div class="class-desc">${c.description}</div><div class="class-stats">${c.stats}</div>`;
  card.addEventListener('click',()=>selectClass(key)); grid.appendChild(card);
});
function selectClass(key){state.classKey=key;document.querySelectorAll('.class-card').forEach(c=>c.classList.toggle('selected',c.dataset.class===key));$('begin-button').disabled=false;$('begin-button').innerHTML=`Begin as ${classes[key].name} <span>→</span>`;}
$('begin-button').addEventListener('click',startGame);
function startGame(){
  const c=classes[state.classKey]; if(!c)return;
  state.hero={...c,hp:c.hp,maxHp:c.hp,focus:c.focus,maxFocus:c.focus,level:1};state.wave=0;state.xp=0;state.potions=2;state.guard=false;state.over=false;state.busy=false;state.log=[];
  $('class-screen').hidden=true;$('game-screen').hidden=false;$('run-stats').hidden=false;
  $('hero-name').textContent=c.name;$('hero-class').textContent=c.title;$('hero-figure').textContent=c.icon;$('hero-scene-name').textContent=c.name.toUpperCase();
  makeActions();startEncounter(0);
}
function startEncounter(index){
  state.wave=index;state.guard=false;state.stunned=false;state.busy=false;
  const base=encounters[index];const scale=1+(state.hero.level-1)*.12;
  state.enemy={...base,maxHp:Math.round(base.hp*scale),hp:Math.round(base.hp*scale),attack:Math.round(base.attack*scale)};
  $('encounter-label').textContent=base.boss?'FINAL ENCOUNTER':'ENCOUNTER 0'+(index+1);
  $('difficulty-label').textContent=base.boss?'THE LAST FLAME':'Threat rises';
  $('enemy-count').textContent='0'+(index+1)+' / 05';$('scene-caption').textContent=base.caption;
  $('enemy-name').textContent=base.name;$('enemy-scene-name').textContent=base.name.toUpperCase();$('enemy-figure').textContent=base.icon;
  $('scene').classList.toggle('boss-scene',!!base.boss);$('enemy-combatant').style.filter=base.boss?'drop-shadow(0 0 15px #e2673c)':'';
  chooseIntent();updateUI();addLog(`<span class="log-highlight">${base.line}</span>`);
}
function makeActions(){const c=state.hero;const items=[['attack','⚔','Attack','A steady strike',''],['skill',c.skillIcon,c.skill,c.skillText,`${c.maxFocus} focus`],['guard','⛨','Brace','Reduce next hit by half',''],['potion','✚','Potion','Restore 14 HP','']];
  $('action-grid').innerHTML=items.map(([id,icon,name,detail,cost])=>`<button class="action-button" data-action="${id}"><span class="action-icon">${icon}</span><span><b class="action-name">${name}</b><small class="action-detail">${detail}</small></span>${cost?`<small class="action-cost">${cost}</small>`:''}</button>`).join('');
  document.querySelectorAll('.action-button').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));
}
function chooseIntent(){
  if(!state.enemy)return;
  const e=state.enemy;let roll=Math.random();
  if(e.boss&&roll<.4)state.intent={type:'heavy',title:'Gathering cinder',copy:'A devastating flame is coming.',symbol:'☄'};
  else if(roll<.29)state.intent={type:'guard',title:'Shifting stance',copy:'The enemy is bracing for a blow.',symbol:'⛨'};
  else if(roll<.58)state.intent={type:'heavy',title:e.boss?'Dragonfire breath':'Heavy strike',copy:'A powerful attack is winding up.',symbol:e.boss?'☄':'⚔'};
  else state.intent={type:'attack',title:'Preparing to strike',copy:'A quick attack is coming your way.',symbol:'⚔'};
  $('intent-title').textContent=state.intent.title;$('intent-copy').textContent=state.intent.copy;$('intent-symbol').textContent=state.intent.symbol;
}
function act(action){if(state.over||state.busy)return;const h=state.hero,e=state.enemy;
  if(action==='potion'&&state.potions<=0){toast('No potions remain.');return;}
  if(action==='potion'&&h.hp===h.maxHp){toast('You are already at full health.');return;}
  if(action==='skill'&&h.focus<state.hero.maxFocus){toast('Your focus is not ready yet.');return;}
  state.busy=true;setActionsDisabled(true);
  if(action==='attack'){
    const damage=rand(5,8)+h.attack;damageEnemy(damage,`${h.name} strikes for ${damage} damage.`);
  } else if(action==='skill'){
    h.focus=0;const dmg=state.classKey==='knight'?11+h.attack:state.classKey==='mage'?14+h.attack:13+h.attack;
    damageEnemy(dmg,`${h.skill} hits for ${dmg} damage!`);
    if(state.classKey==='knight'&&state.enemy.hp>0){state.stunned=true;addLog('The foe is staggered and will lose its next turn.');}
    if(state.classKey==='ranger'&&state.enemy.hp>0){h.focus=1;addLog('A true shot restores a little focus.');}
  } else if(action==='guard'){
    state.guard=true;h.focus=Math.min(h.maxFocus,h.focus+1);addLog(`${h.name} braces. The next blow will be softened.`);showToast('Guard raised · focus +1');
  } else if(action==='potion'){
    const heal=Math.min(14,h.maxHp-h.hp);h.hp+=heal;state.potions--;addLog(`A healing draught restores ${heal} HP.`);showToast(`Restored ${heal} HP`);
  }
  updateUI();
  if(e.hp<=0){setTimeout(()=>winEncounter(),400);return;}
  setTimeout(enemyTurn,430);
}
function damageEnemy(dmg,message){let actual=dmg;if(state.enemy.hp>0){state.enemy.hp=Math.max(0,state.enemy.hp-actual);flash('enemy-combatant');floatText(`−${actual}`);addLog(message);}}
function enemyTurn(){if(state.over)return;const e=state.enemy,h=state.hero;
  if(state.stunned){state.stunned=false;addLog(`${e.name} reels, unable to act.`);state.busy=false;chooseIntent();updateUI();setActionsDisabled(false);return;}
  if(state.intent.type==='guard'){
    e.guard=true;addLog(`${e.name} shifts into a guarded stance.`);showToast('Enemy is guarding');
  }else{
    let dmg=state.intent.type==='heavy'?Math.ceil(e.attack*1.65):e.attack;
    if(e.boss&&state.intent.type==='heavy')dmg+=3;
    if(state.guard){dmg=Math.max(1,Math.ceil(dmg*.48)-h.armor);state.guard=false;addLog(`Your brace absorbs much of the blow. ${e.name} deals ${dmg} damage.`);}
    else{dmg=Math.max(1,dmg-h.armor);addLog(`${e.name} hits you for ${dmg} damage.`);}
    if(e.guard){dmg=Math.max(1,dmg-4);e.guard=false;addLog('Their guard softens your counterblow.');}
    h.hp=Math.max(0,h.hp-dmg);flash('hero-combatant');floatText(`−${dmg}`);if(h.hp<=0){updateUI();setTimeout(loseGame,500);return;}
  }
  h.focus=Math.min(h.maxFocus,h.focus+1);state.busy=false;chooseIntent();updateUI();setActionsDisabled(false);
}
function winEncounter(){const defeated=state.enemy;state.busy=false;state.xp+=defeated.xp;state.hero.focus=Math.min(state.hero.maxFocus,state.hero.focus+1);updateUI();
  if(defeated.boss){state.over=true;showResult(true);return;}
  const heal=Math.min(6,state.hero.maxHp-state.hero.hp);state.hero.hp+=heal;
  $('result-eyebrow').textContent='A MOMENT OF RESPITE';$('result-title').textContent='The path is clear.';$('result-copy').textContent=`${defeated.name} falls. You take a breath before the next danger finds you.`;$('reward-line').textContent=`✦  +${defeated.xp} XP     ·     +${heal} HP     ·     +1 focus`;$('result-button').textContent='Continue onward →';$('modal-backdrop').hidden=false;state.pendingNext=state.wave+1;
}
function showResult(won){$('result-eyebrow').textContent=won?'THE WYRM IS SLAIN':'YOUR TALE ENDS HERE';$('result-title').textContent=won?'A legend is born.':'The dark claims another.';$('result-copy').textContent=won?'The Cinder Wyrm falls, and dawn returns to the wilderness. Your name will be carried by every road.':`You reached encounter ${String(state.wave+1).padStart(2,'0')} and earned ${state.xp} experience. The wilderness remembers.`;$('reward-line').textContent=won?`✦  FINAL VICTORY     ·     ${state.xp} XP EARNED`:`✦  LEVEL ${state.hero.level}     ·     ${state.xp} XP EARNED`;$('result-button').textContent=won?'Play again →':'Rise again →';$('modal-backdrop').hidden=false;}
$('result-button').addEventListener('click',()=>{ $('modal-backdrop').hidden=true;if(state.over){$('game-screen').hidden=true;$('run-stats').hidden=true;$('class-screen').hidden=false;$('screen-title').innerHTML='Your legend begins <i>here.</i>'; $('eyebrow').textContent='A TALE OF STEEL & SORCERY';return;} if(state.xp>=state.hero.level*50){state.xp-=state.hero.level*50;state.hero.level++;state.hero.maxHp+=5;state.hero.hp=Math.min(state.hero.maxHp,state.hero.hp+8);state.hero.maxFocus++;state.hero.focus=state.hero.maxFocus;state.hero.attack+=1;makeActions();toast(`Level up! You are now level ${state.hero.level}.`);}startEncounter(state.pendingNext);});
function loseGame(){state.over=true;showResult(false);}
function updateUI(){if(!state.hero)return;const h=state.hero,e=state.enemy;
  $('hero-hp-text').textContent=`${h.hp} / ${h.maxHp}`;$('enemy-hp-text').textContent=`${Math.max(0,e.hp)} / ${e.maxHp}`;
  $('hero-health').style.width=`${h.hp/h.maxHp*100}%`;$('enemy-health').style.width=`${Math.max(0,e.hp)/e.maxHp*100}%`;
  $('level-label').textContent=`LVL ${h.level}`;$('xp-label').textContent=`${state.xp} XP`;$('focus-label').textContent=`${h.focus} FOCUS`;$('potion-label').textContent=state.potions;
  $('header-wave').textContent=e.boss?'THE CINDER WYRM':`ENCOUNTER ${String(state.wave+1).padStart(2,'0')}`;
  $('hero-health').style.background=h.hp/h.maxHp<.3?'#bb6a5a':'';
  const skill=document.querySelector('[data-action="skill"]');if(skill)skill.disabled=h.focus<h.maxFocus||state.busy;
  const potion=document.querySelector('[data-action="potion"]');if(potion)potion.disabled=state.potions===0||h.hp===h.maxHp||state.busy;
}
function setActionsDisabled(disabled){document.querySelectorAll('.action-button').forEach(b=>{if(b.dataset.action==='skill')b.disabled=disabled||state.hero.focus<state.hero.maxFocus;else if(b.dataset.action==='potion')b.disabled=disabled||state.potions===0||state.hero.hp===state.hero.maxHp;else b.disabled=disabled;});}
function addLog(html){state.log.unshift(html);state.log=state.log.slice(0,3);$('battle-log').innerHTML=state.log.map(line=>`<div class="log-entry">${line}</div>`).join('');}
function rand(min,max){return Math.floor(Math.random()*(max-min+1))+min;}
function flash(target){const node=$(target);node.classList.remove('hit');void node.offsetWidth;node.classList.add('hit');$('hit-flash').classList.remove('flash');void $('hit-flash').offsetWidth;$('hit-flash').classList.add('flash');}
function floatText(text){const node=$('scene-toast');node.textContent=text;node.classList.remove('show');void node.offsetWidth;node.classList.add('show');}
let toastTimer;function toast(message){const node=$('toast');node.textContent=message;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),1900);}function showToast(message){toast(message);}
$('retreat-button').addEventListener('click',()=>{if(confirm('Abandon this run and choose a new hero?')){state.over=true;$('game-screen').hidden=true;$('run-stats').hidden=true;$('class-screen').hidden=false;$('screen-title').innerHTML='Your legend begins <i>here.</i>';$('eyebrow').textContent='A TALE OF STEEL & SORCERY';}});
$('sound-toggle').addEventListener('click',()=>{state.sound=!state.sound;$('sound-toggle').innerHTML=state.sound?'♫ <span>Sound on</span>':'♫ <span>Sound off</span>';toast(state.sound?'Sound effects enabled':'Sound effects muted');});

